mapper.select:
select count(*) as totalCount , count(*) filter (where r.status = '예약완료') as reservedCount , count(*) filter (where r.status = '인증완료') as verifiedCount , count(*) filter (where r.status = '충전중') as chargingCount , count(*) filter (where r.status = '완료') as completedCount , count(*) filter (where r.status = '취소') as canceledCount , count(*) filter (where r.status = '노쇼') as noShowCount from reservation r join app_member m on r.member_id = m.member_id join vehicle v on r.vehicle_id = v.vehicle_id join vehicle_model vm on v.model_id = vm.model_id join charger c on r.charger_id = c.charger_id join charging_station cs on c.station_id = cs.station_id
and r.status = #{status}
and r.reservation_date >= #{startDate}
and r.reservation_date <= #{endDate}
and m.member_name ilike concat('%', #{keyword}, '%')
and cs.station_name ilike concat('%', #{keyword}, '%')
and vm.model_name ilike concat('%', #{keyword}, '%')
and ( m.member_name ilike concat('%', #{keyword}, '%') or cs.station_name ilike concat('%', #{keyword}, '%') or vm.model_name ilike concat('%', #{keyword}, '%') or c.charger_name ilike concat('%', #{keyword}, '%') )

select count(*) from reservation r join app_member m on r.member_id = m.member_id join vehicle v on r.vehicle_id = v.vehicle_id join vehicle_model vm on v.model_id = vm.model_id join charger c on r.charger_id = c.charger_id join charging_station cs on c.station_id = cs.station_id
and r.status = #{status}
and r.reservation_date >= #{startDate}
and r.reservation_date <= #{endDate}
and m.member_name ilike concat('%', #{keyword}, '%')
and cs.station_name ilike concat('%', #{keyword}, '%')
and vm.model_name ilike concat('%', #{keyword}, '%')
and ( m.member_name ilike concat('%', #{keyword}, '%') or cs.station_name ilike concat('%', #{keyword}, '%') or vm.model_name ilike concat('%', #{keyword}, '%') or c.charger_name ilike concat('%', #{keyword}, '%') )

select r.reservation_id as reservationId , concat('RSV-', lpad(r.reservation_id::text, 6, '0')) as reservationNo , r.start_time as startTime , m.member_name as memberName , concat(vm.manufacturer, ' ', vm.model_name) as vehicleName , cs.station_name as stationName , c.charger_name as chargerName , r.current_soc as currentSoc , r.target_soc as targetSoc , r.estimated_minutes as estimatedMinutes , r.estimated_cost as estimatedCost , r.auth_code as authCode , r.status as status from reservation r join app_member m on r.member_id = m.member_id join vehicle v on r.vehicle_id = v.vehicle_id join vehicle_model vm on v.model_id = vm.model_id join charger c on r.charger_id = c.charger_id join charging_station cs on c.station_id = cs.station_id
and r.status = #{status}
and r.reservation_date >= #{startDate}
and r.reservation_date <= #{endDate}
and m.member_name ilike concat('%', #{keyword}, '%')
and cs.station_name ilike concat('%', #{keyword}, '%')
and vm.model_name ilike concat('%', #{keyword}, '%')
and ( m.member_name ilike concat('%', #{keyword}, '%') or cs.station_name ilike concat('%', #{keyword}, '%') or vm.model_name ilike concat('%', #{keyword}, '%') or c.charger_name ilike concat('%', #{keyword}, '%') )
order by r.start_time desc limit #{size} offset #{offset}
